import sys
from collections import defaultdict

sys.setrecursionlimit(2 * 10**5)

def dfs(node, parent, tree, values, bit):
    mask = 1 << bit
    if values[node - 1] & mask:
        return 1
    return 0

def solve(N, K, values, edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    max_and = 0
    for bit in range(31, -1, -1):
        mask = 1 << bit
        count = 0
        visited = [False] * (N + 1)

        def dfs(node):
            nonlocal count
            visited[node] = True
            if values[node - 1] & mask:
                count += 1
            for neighbor in tree[node]:
                if not visited[neighbor]:
                    dfs(neighbor)

        for node in range(1, N + 1):
            if not visited[node]:
                dfs(node)

        if count >= K:
            max_and |= mask
            for node in range(1, N + 1):
                if visited[node]:
                    values[node - 1] &= ~mask

    return max_and

def main():
    input_data = sys.stdin.read().splitlines()
    T = int(input_data[0])
    index = 1
    results = []
    for _ in range(T):
        N, K = map(int, input_data[index].split())
        values = list(map(int, input_data[index + 1].split()))
        edges = []
        for i in range(N - 1):
            u, v = map(int, input_data[index + 2 + i].split())
            edges.append((u, v))
        index += 2 + (N - 1)
        results.append(solve(N, K, values, edges))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
